import { supabase } from './supabase';

/**
 * Fetch hazards and their consequences by event ID.
 */
export async function getHazardsByEventId(eventId) {
  try {
    const { data: hazards, error } = await supabase
      .from('hira_hazards')
      .select(`
        id,
        description,
        hira_consequences (
          id,
          description,
          current_controls
        )
      `)
      .eq('event_id', eventId)
      .order('created_at', { ascending: true });

    if (error) {
      console.error('Error fetching hazards:', error);
      throw error;
    }

    return hazards.map(hazard => ({
      hazard_id: hazard.id,
      description: hazard.description,
      consequences: hazard.hira_consequences.map(consequence => ({
        id: consequence.id,  // Keep the original id from the consequences table
        description: consequence.description,
        currentControls: consequence.current_controls,
      }))
    }));
  } catch (error) {
    console.error('Error getting hazards:', error);
    throw error;
  }
}

/**
 * Update hazards and their consequences for a specific event.
 */
export async function updateHazards(eventId, hazardsData) {
  try {
    // Fetch existing hazards with their consequences for the event
    const { data: existingHazards, error: fetchError } = await supabase
      .from('hira_hazards')
      .select(`
        id,
        description,
        hira_consequences (
          id,
          description,
          current_controls
        )
      `)
      .eq('event_id', eventId);

    if (fetchError) throw fetchError;

    // Create a map of existing hazards and consequences
    const existingHazardMap = new Map(existingHazards?.map(h => [h.description, h]) || []);

    // Process each hazard
    const hazardPromises = hazardsData.map(async hazard => {
      let hazardRecord;
      const existingHazard = existingHazardMap.get(hazard.description);

      if (existingHazard) {
        // Update existing hazard
        const { data: updatedHazard, error: hazardError } = await supabase
          .from('hira_hazards')
          .update({
            description: hazard.description,
            updated_at: new Date().toISOString()
          })
          .eq('id', existingHazard.id)
          .select()
          .single();

        if (hazardError) throw hazardError;
        hazardRecord = updatedHazard;
      } else {
        // Create new hazard
        const { data: createdHazard, error: hazardError } = await supabase
          .from('hira_hazards')
          .insert({
            event_id: eventId,
            description: hazard.description,
            created_at: new Date().toISOString(),
            updated_at: new Date().toISOString()
          })
          .select()
          .single();

        if (hazardError) throw hazardError;
        hazardRecord = createdHazard;
      }

      // Process consequences
      const consequencePromises = hazard.consequences.map(async consequence => {
        // Check if this consequence already exists for this hazard
        const existingConsequence = existingHazard?.hira_consequences?.find(
          c => c.description === consequence.description
        );

        if (existingConsequence) {
          // Update existing consequence
           const { data: updatedConsequence, error: consequenceError } = await supabase
            .from('hira_consequences')
            .update({
              description: consequence.description,
              current_controls: consequence.currentControls,
              updated_at: new Date().toISOString()
            })
            .eq('id', existingConsequence.id)
            .select()
            .single();

          if (consequenceError) throw consequenceError;

          return {
            id: existingConsequence.id,
            description: updatedConsequence.description,
            currentControls: updatedConsequence.current_controls
          };
        } else {
          // Create new consequence and risk assessment
          const { data: createdConsequence, error: consequenceError } = await supabase
            .from('hira_consequences')
            .insert({
              hazard_id: hazardRecord.id,
              description: consequence.description,
              current_controls: consequence.currentControls,
              created_at: new Date().toISOString(),
              updated_at: new Date().toISOString()
            })
            .select()
            .single();

          if (consequenceError) throw consequenceError;

          // Create risk assessment for new consequence
          const { error: assessmentError } = await supabase
            .from('hira_risk_assessments')
            .insert({
              consequence_id: createdConsequence.id,
              created_at: new Date().toISOString(),
              updated_at: new Date().toISOString()
            });

          if (assessmentError) throw assessmentError;

          return {
            id: createdConsequence.id,
            description: createdConsequence.description,
            currentControls: createdConsequence.current_controls
          };
        }
      });

      const consequences = await Promise.all(consequencePromises);

      return {
        hazard_id: hazardRecord.id,
        description: hazardRecord.description,
        consequences
      };
    });

    const results = await Promise.all(hazardPromises);
    return results.map(hazardResult => ({
      hazard_id: hazardResult.hazard_id,
      description: hazardResult.description,
      consequences: hazardResult.consequences.map(consequence => ({
        consequence_id: consequence.id,
        description: consequence.description,
        currentControls: consequence.currentControls
      }))
    }));
  } catch (error) {
    console.error('Error updating hazards:', error);
    throw error;
  }
}

/**
 * Delete all hazards and their consequences for a specific event.
 */
export async function deleteHazards(eventId) {
  try {
    const { error } = await supabase
      .from('hira_hazards')
      .delete()
      .eq('event_id', eventId);

    if (error) throw error;
  } catch (error) {
    console.error('Error deleting hazards:', error);
    throw error;
  }
}
